class Pool<T>(size: Int, private val create: () -> T) {
    private val permits = Semaphore(size)
    private val idle = ArrayDeque<T>()
    suspend fun <R> use(block: (T) -> R): R = permits.withPermit {
        val res = idle.removeLastOrNull() ?: create()
        try { block(res) } finally { idle.addLast(res) }
    }
}
